import re

def parse_line(line):
    # Strip whitespace around keys and values
    line = line.strip()
    if not line or line.startswith('#'):
        return None
    key, value = line.split('=', 1)
    return key.strip(), value.strip()

def normalize_defaults(defaults):
    return {k.strip(): v.strip() for k, v in defaults.items()}

def load_config(lines, defaults=None):
    if defaults is None:
        defaults = {}
    config = {}
    for line in lines:
        key, value = parse_line(line)
        if key and value:
            config[key] = value
    config.update(normalize_defaults(defaults))
    return config

def reject_malformed_line(line):
    if '=' not in line:
        raise ValueError('Malformed non-comment line')

